insert into public.quiz_questions
  (qid, unit, sub, difficulty, question, choice_a, choice_b, choice_c, choice_d, correct, explanation, source, active)
values
  ('SHIORI-001', '安全のしおり', '安全理念', '★', 'ベステラの安全理念「基本3ヶ条」として定められているものはどれか。', '納期は全てに優先する', '品質は全てに優先する', '安全は全てに優先する', 'コストは全てに優先する', 'C', '基本3ヶ条は「①安全は全てに優先する ②自ら考え、工夫し、努力する ③環境に配慮し、循環社会に貢献する」。安全が最優先される。', '安全のしおり 工事部員心得 安全理念 基本3ヶ条', true),
  ('SHIORI-002', '安全のしおり', '一般事項', '★★', '客先・工場内の現場での行為として、規則上「禁止」されているものはどれか。', '客先が許可した場所での休憩', '支給された作業服の着用', '無許可での撮影・SNSへのアップロード', '許可された場所での飲食', 'C', '客先・工場内現場での無許可の撮影・スケッチ・SNSアップロードは禁止。現場によっては通話も禁止される場合があり、客先ルールをよく確認する。', '安全のしおり 1-1 現場 ②', true),
  ('SHIORI-003', '安全のしおり', '飲酒・喫煙', '★', '現場での喫煙に関する規則として正しいものはどれか。', '許可された場所以外での喫煙は、携帯灰皿を使用しても不可', '構内駐車中の車内なら喫煙してよい', '携帯灰皿を使えばどこでも喫煙してよい', '移動中の車内なら喫煙してよい', 'A', '許可を受けた場所以外での飲食・喫煙は禁止。喫煙は携帯灰皿を使用しても不可で、構内駐車・移動中の車内なども不可。', '安全のしおり 1-2 飲食・飲酒・喫煙 ①', true),
  ('SHIORI-004', '安全のしおり', '服装(現場)', '★', '現場での服装規則として正しいものはどれか。', '夏場は半袖・腕まくりで作業してよい', 'ヘルメットはアゴ紐をしっかり掛けて着用する', '暑い日は手ぬぐいを首に掛けてよい', 'ヘルメットの下に頭巻きをしてよい', 'B', 'ヘルメットはアゴ紐をしっかり掛ける。現場内では半袖・腕まくり作業は禁止、手ぬぐい・タオルの首(腰)掛け禁止、ヘルメット下の頭巻きも禁止。', '安全のしおり 1-3 服装(現場) ①④⑤', true),
  ('SHIORI-005', '安全のしおり', '交通規則', '★★', '自動車の運転に関する規則として誤っているものはどれか。', '連続運転は2時間ごとに休憩を取る', '社有車はベステラ社員以外も運転してよい', '運転中の携帯電話の操作は禁止', '運転業務の開始前後にアルコールチェックを行う', 'B', '社有車はベステラ社員以外の運転を禁止。連続運転は2時間で休憩、運転中の携帯操作禁止、運転業務の開始前後にアルコールチェックを行う。', '安全のしおり 1-4 交通規則 ②③⑨⑩', true),
  ('SHIORI-006', '安全のしおり', '作業前', '★★', 'プラント等の現場で作業に着手する際、着工許可を得る相手として正しいものはどれか。', '自社の上長', '玉掛け作業者', '協力会社責任者', '客先責任者', 'D', 'プラント等の現場では、作業の着手に客先責任者の着工許可を得る。', '安全のしおり 2-1 作業前 ②', true),
  ('SHIORI-007', '安全のしおり', '作業中', '★★★', '当初の予定になかった作業（予定外作業）が発生したときの正しい対応はどれか。', 'そのまま継続し、後で報告する', '作業指揮者の判断だけで進める', '一度作業を止め、客先に確認し、承認後に再KYを行ってから作業する', '翌日の朝礼で共有してから着手する', 'C', '予定外作業が発生したら一度作業を止め、客先に確認し作業手順を確認、客先承認後に再KYを行ってから作業する。', '安全のしおり 2-2 作業中 ②', true),
  ('SHIORI-008', '安全のしおり', '緊急時対応', '★★', '事故等の連絡を行う際の正しい方法はどれか。', '口頭で簡単に伝える', '5W1Hで的確に行う', 'メールのみで連絡する', '連絡に集中し、現場把握は後回しにする', 'B', '事故等の連絡は5W1Hで的確に行う。ただし連絡に気をとられ過ぎず、現場の把握・安全確保を確実に実施する。', '安全のしおり 2-6 緊急時対応 ③④', true),
  ('SHIORI-009', '安全のしおり', '現場管理(元請)', '★★', '元請として行うべき事項として正しいものはどれか。', '作業場所の巡視は週1回でよい', '連絡調整は協力会社に任せる', '協議会組織を設置し毎月1回以上開催する', '巡視は災害発生時のみ行う', 'C', '元請は協議会組織を設置し毎月1回以上開催、作業間の連絡調整、1日1回以上の作業場所巡視等を行う。', '安全のしおり 3 現場管理(元請) ①③', true),
  ('SHIORI-010', '安全のしおり', '火気作業', '★★', '火気作業を行った後の残火確認について、正しいものはどれか。', '30分以上', '10分以上', '5分以上', '確認は不要', 'A', '火気作業を行った際は30分以上、残火確認を確実に行う。', '安全のしおり 4-2 火気作業 ⑦', true),
  ('SHIORI-011', '安全のしおり', '火気作業', '★★★', 'アセチレンボンベの取り扱いとして正しいものはどれか。', '立てて使用し、転倒防止のチェーン(2重)等で固縛する', '横に寝かせて使用する', '直射日光下で50度まで許容される', '固縛は不要', 'A', 'アセチレンボンベは必ず立てて使用し、転倒防止用チェーン(2重)等で固縛。直射日光を避け40度以下に保つため防炎シート等で被う。', '安全のしおり 4-2 火気作業 ⑤', true),
  ('SHIORI-012', '安全のしおり', '高所作業', '★★', '墜落制止用器具に関する規則として正しいものはどれか。', 'フルハーネス型は10m以上で義務付けられる', '3m以上で器具を使用すればよい', '2m以上で器具を使用し、5m以上でフルハーネス型を使用する', '使用期限切れの器具でも持込み可', 'C', '2m以上の高所で墜落制止用器具を使用し、5m以上でフルハーネス型が義務。持込時点検を実施し、使用期限切れ・規格外器具の持込は禁止。', '安全のしおり 4-3 高所作業 ②', true),
  ('SHIORI-013', '安全のしおり', '高所作業', '★★', 'フルハーネス型墜落制止用器具を使用するために必要なものはどれか。', '特別教育の受講', '作業主任者の選任', '技能講習', '運転免許', 'A', 'フルハーネス型墜落制止用器具を使用するときは「特別教育」を受講しなければならない。', '安全のしおり 4-3 高所作業 ③', true),
  ('SHIORI-014', '安全のしおり', '高所作業', '★★★', '単管手すりで開口部を養生する場合の手すり高さの基準として正しいものはどれか。', '85cm以上', '75cm以上', '95cm以上', '105cm以上', 'A', '単管手すりで養生する場合、手すり高さ85cm以上、中桟35〜50cm、巾木15cm以上を確保する。', '安全のしおり 4-3 高所作業 図5(開口部養生例)', true),
  ('SHIORI-015', '安全のしおり', '揚重作業(玉掛)', '★★★', '4月に行う吊具(玉掛用具)の月例点検で、使用可能と判定した用具に貼るビニールテープの色はどれか。', '緑', '黄', '白', '赤', 'C', '1・5・9月＝緑、2・6・10月＝黄、3・7・11月＝赤、4・8・12月＝白。発注者・元請に指定色がある場合はそちらを優先する。', '安全のしおり 4-4 揚重作業 ③', true),
  ('SHIORI-016', '安全のしおり', '揚重作業(玉掛)', '★★', 'クレーン等を用いた揚重作業について、正しいものはどれか。', '吊り荷の下に入ってもよい', 'ワイヤーによる1本吊りは厳禁である', 'アウトリガーは張り出さなくてよい', '介錯ロープは使用しない', 'B', 'クレーン等を用いた揚重作業ではワイヤーによる1本吊りは厳禁。吊り荷の下に入らない、アウトリガーは原則最大張出で使用、介錯ロープを使用する。', '安全のしおり 4-4 揚重作業 ⑤(他②④⑦)', true),
  ('SHIORI-017', '安全のしおり', '重機作業', '★★', 'バックホウの運転席から離脱する際の措置として正しいものはどれか。', 'バケットを上げたままにする', 'バケットを地面に下ろし、エンジンを止め、走行ブレーキを掛けてキーを抜く', 'エンジンを掛けたままにする', 'キーは付けたままでよい', 'B', '運転席を離れる際はバケット等を地面に下ろし、エンジンを止め、走行ブレーキを掛けてキーを抜き、逸走を防止する。', '安全のしおり 4-5 重機作業(バックホウ) ⑦', true),
  ('SHIORI-018', '安全のしおり', '重機作業', '★★★', 'バックホウによる荷の吊り上げ作業が認められる条件として正しいものはどれか。', '作業の性質上やむを得ない等の場合で、かつクレーン機能付き重機・移動式クレーン資格・玉掛資格・吊具点検・フック外れ止め等の安全措置を満たす場合のみ', '急いでいるときは無条件で可能', '作業者の判断でいつでも可能', '玉掛資格があれば他の措置は不要', 'A', 'バックホウの荷吊り上げは「作業の性質上やむを得ない/安全な作業遂行上必要」かつ「クレーン機能付き重機・移動式クレーン資格・立入禁止措置・玉掛資格・吊具点検・フック外れ止め等」を共に満たす場合のみ可能。', '安全のしおり 4-5 重機作業(バックホウ) ⑩', true),
  ('SHIORI-019', '安全のしおり', '有害物取扱い', '★★', '化学物質を取り扱う作業で、まず参照してリスクアセスメントを行う資料はどれか。', '作業日報', 'SDS(安全データシート)', '社員名簿', '出面表', 'B', '化学物質の取扱いはSDS(安全データシート)を参照してリスクアセスメントを実施し、関係者に周知する。', '安全のしおり 4-6 有害物取扱い ①', true),
  ('SHIORI-020', '安全のしおり', '酸欠作業', '★', '酸素欠乏危険場所に立ち入る前、安全を確認する酸素濃度の基準はどれか。', '15%以上', '16%以上', '18%以上', '21%以上', 'C', '作業主任者が酸素濃度等を測定し、酸素濃度18%以上の安全を確認してから酸欠等危険場所に立ち入る。', '安全のしおり 4-7 酸素欠乏症等作業 ①', true),
  ('SHIORI-021', '安全のしおり', '酸欠作業', '★★★', '酸素濃度計の校正期間の目安として正しいものはどれか。', '1ヶ月', '6ヶ月', '1年', '校正は不要', 'C', '酸素濃度計等の校正期間は1年を目安に行う。使っていなくてもセンサーは劣化する。', '安全のしおり 4-7 酸素欠乏症等作業 ⑩', true),
  ('SHIORI-022', '安全のしおり', '区画(工事エリア)', '★★', '作業エリアの区画・開口部について正しいものはどれか。', '重機作業と作業員が混在しても区画は不要', '資機材の仮置きはどこでもよい', '産業廃棄物の保管場所に囲いは不要', '開口部は丈夫な蓋等で塞ぐか、周囲を手すり等で囲んで立入禁止とする', 'D', '開口部は丈夫な蓋等で覆って塞ぐか、周囲を手すり等で囲んで立入禁止とする。重機と作業員が混在する場合はバリケード等で区画し、区画できない場合は誘導員(監視人)を配置する。', '安全のしおり 4-1 区画 ④⑦', true),
  ('SHIORI-023', '安全のしおり', '作業後', '★★', '石綿・ダイオキシン特定作業等における記録の取り扱いとして正しいものはどれか。', '記録は不要', '客先には報告しない', '口頭報告のみでよい', '法令に則り記録を保管する', 'D', '日々の現場で日誌・日報を作成・保管し、石綿・ダイオキシン特定作業等においては法令に則り記録を保管する。', '安全のしおり 2-3 作業後 ③', true),
  ('SHIORI-024', '安全のしおり', '作業前', '★★', '有資格作業における作業前の確認事項として正しいものはどれか。', '資格の有無は自己申告でよい', '有資格作業では資格証の原本確認を行う', '確認は作業後でよい', 'コピーがあれば原本は不要', 'B', '有資格作業においては原本の確認を行う。各作業に共通して、作業開始前に資格証の携帯を確認する。', '安全のしおり 2-1 作業前 ⑥(4章共通注記)', true),
  ('REG-001', '規程類', '管理体制', '★★', '当社における総括安全衛生管理者は、原則として誰が務めると定められているか。', '代表取締役', '安全衛生室長', '工事部長', 'プラント事業本部長', 'D', '総括安全衛生管理者は原則として事業主だが、当社では別に選任し『プラント事業本部長』を充てる(第6条3項)。', '安全衛生管理規程 第6条', true),
  ('REG-002', '規程類', '管理体制', '★★', '総括安全衛生管理者の代理者は、原則として誰と定められているか。', '安全衛生室長', '各地域事務所長', '産業医', '工事部長', 'D', '労働安全衛生規則第3条の総括安全衛生管理者の代理者は、原則として工事部長とする(第8条)。', '安全衛生管理規程 第8条', true),
  ('REG-003', '規程類', '管理体制', '★★', '安全衛生担当者の『正担当者』は誰か。', '事業本部 安全衛生室長', '工事部長', '産業医', '地域事務所長', 'A', '安全衛生担当者は、事業本部 安全衛生室長を正担当者、安全衛生室員を副担当者とする(第13条)。', '安全衛生管理規程 第13条', true),
  ('REG-004', '規程類', '管理体制', '★★★', '化学物質管理者の配置について、規程で定められているものはどれか。', '全社で1名を選任', '選任は任意', '現場ごとに3名以上', '地域事務所ごとに1名以上を配置', 'D', '化学物質管理者は法の定めにより、地域事務所毎に1名以上を配置する(第19条の2)。', '安全衛生管理規程 第19条の2', true),
  ('REG-005', '規程類', '衛生管理', '★★★', '当社が『第二種衛生管理者』を衛生管理者として選任しない理由として正しいものはどれか。', '人数が足りないため', '受託工事にアスベスト等の有害業務が伴うため', '費用が高いため', '法律で禁止されているため', 'B', '受託工事における危険・有害業務(アスベスト等取扱)が伴うため、第二種ではなく第一種衛生管理者または衛生工学衛生管理者を選任する(第11条)。', '安全衛生管理規程 第11条', true),
  ('REG-006', '規程類', '災害対応', '★★★', '災害が発生した場合の最優先行動として正しいものはどれか。', '被災者の救助を最優先する(酸欠等で二次災害が予想される場合は予備の安全装備を確認後・単独行動は厳禁)', 'まず写真撮影と記録を行う', '上司の到着を待ってから動く', '現場保存を最優先する', 'A', '現認者・周辺者は直ちに被災者救助を第一優先とする。ただし酸素欠乏等で二次災害が予想される場合は予備の安全装備品の確認後に救助し、1人での救助行動は厳禁(第35条)。', '安全衛生管理規程 第35条', true),
  ('REG-007', '規程類', '災害対応', '★★', '労働災害発生時、所轄の労働基準監督署へ通報を行うのは誰か。', '雇用管理責任者', '地域事務所長', '現認者', '産業医', 'A', '通報は現認者→消防署・警察署→地域事務所長→所属部長→事業主・総括安全衛生管理者・雇用管理責任者の順で報告し、労基署への通報は雇用管理責任者が行う(第35条2項)。', '安全衛生管理規程 第35条', true),
  ('REG-008', '規程類', '災害対応', '★★', '被災者は出なかったが、人身災害を起こすおそれのある事故・事象(ヒヤリ・ハット)が発生した場合の対応はどれか。', '検討会を開き事故報告書を作成して提出する', '記録は不要', '口頭報告のみでよい', '翌年の安全大会で共有する', 'A', '被災者がなくても人身災害のおそれのある事故・事象(ヒヤリ・ハット)は、災害に準じて検討会を開き、事故報告書を作成して工事部長経由で安全衛生担当者へ提出する(第39条)。', '安全衛生管理規程 第39条', true),
  ('REG-009', '規程類', '教育', '★★', '安全衛生管理規程で会社が実施すると定める教育訓練に『含まれない』ものはどれか。', '接客マナー研修', '監督者安全衛生教育', '免許取得・技能教育・特別教育', '雇入れ・作業内容変更時教育', 'A', '実施する教育訓練は①雇入れ・作業内容変更時②監督者安全衛生教育③免許取得・技能教育・特別教育④職場小集団リーダー教育 等(第26条)。接客マナー研修は含まれない。', '安全衛生管理規程 第26条', true),
  ('REG-010', '規程類', '懲戒', '★★', '規程・マニュアル等を遵守せず重大な災害を発生させた場合の措置はどれか。', '口頭注意のみ', '罰則はない', '就業規則の定めにより懲戒に処することがある', '始末書のみ', 'C', '規程・マニュアル等の遵守をしないことにより重大な災害を発生させたときは、就業規則の定めによる懲戒に処することがある(第41条)。', '安全衛生管理規程 第41条', true),
  ('REG-011', '規程類', '一般従業員', '★★', '一般従業員の責務として規程に定められているものはどれか。', '巡視は管理者に任せ自身は行わない', '始業に当たり設備・機器・職場環境の安全衛生点検と確認を行う', '教育訓練への参加は任意で不参加でよい', '改善案の提出は禁止されている', 'B', '一般従業員は法令・社内規定の遵守、始業時の安全衛生点検と確認、教育訓練・安全懇談会への参加、改善案の提出等を行う(第17条)。', '安全衛生管理規程 第17条', true),
  ('REG-012', '規程類', 'リスクアセスメント', '★★', 'リスクの大きさの見積り方として正しいものはどれか。', '重大性(重篤度)×頻度(可能性)', '重大性＋頻度', '頻度のみで決める', '費用×作業時間', 'A', 'リスク評価＝重大性(重篤度)×頻度(可能性)。両者を掛け算してリスクの大きさを50〜1で見積もる(第6条)。', 'リスクアセスメント実施マニュアル 第6条', true),
  ('REG-013', '規程類', 'リスクアセスメント', '★★★', 'リスク低減措置を検討する際、最初(最優先)に検討すべき段階はどれか。', '個人用保護具の着用', '物理的対策(手摺・囲い)', '管理的対策(監視人配置等)', '作業方法の検討(危険作業の除去・見直し)', 'D', '低減措置の優先順位は①作業方法の検討(除去・低減)②物理的対策③管理的対策④個人用保護具。安易に個人用保護具の着用でリスク低減を選択してはならない(第6条)。', 'リスクアセスメント実施マニュアル 第6条', true),
  ('REG-014', '規程類', 'リスクアセスメント', '★★★', 'リスクアセスメントで特に重篤度を高く扱う『三大災害』はどれか。', '切創・火災・熱中症', '墜落・重機・土砂崩壊', '感電・転倒・腰痛', '騒音・粉じん・振動', 'B', '墜落災害・重機災害・土砂崩壊災害の三大災害は重篤度の高い災害として扱う(第6条)。', 'リスクアセスメント実施マニュアル 第6条', true),
  ('REG-015', '規程類', 'リスクアセスメント', '★★', 'リスク見積りで優先度A『直ちに対策が必要』と判定される点数はどれか。', '25点以上', '15点以上', '9点以上', '50点ちょうど', 'A', '25点以上=A(直ちに対策)、15点以上=B(抜本的対策)、9点以上=C(何らかの対策)、8点以下=D(現時点で対策不要)(第6条 優先度の決定表)。', 'リスクアセスメント実施マニュアル 第6条 優先度の決定表', true),
  ('REG-016', '規程類', 'リスクアセスメント', '★★', 'リスクアセスメント実施管理者を兼ねるのは誰か。', '職長', '現場代理人', '安全衛生推進者', '玉掛け作業者', 'B', '現場代理人がリスクアセスメント実施管理者の職を兼ね、進行管理・低減措置の優先順位決定・予算化等の責任と権限を有する(第4条)。', 'リスクアセスメント実施マニュアル 第4条', true),
  ('REG-017', '規程類', 'リスクアセスメント', '★★★', 'リスクアセスメント実施記録の保存期間として正しいものはどれか。', '通常1年、石綿含有物の取扱いがある場合は10年', '通常5年、石綿含有物の取扱いがある場合は30年', '通常3年、石綿含有物の取扱いがある場合は40年', '保存は不要', 'C', '工事竣工後は記録を3年間保存。工事内容に石綿含有物質の取扱いがある場合は記録を40年間保存する(第4条)。', 'リスクアセスメント実施マニュアル 第4条', true),
  ('REG-018', '規程類', 'リスクアセスメント', '★★', 'リスクアセスメントを実施する時期に『該当しない』ものはどれか。', '朝の作業開始前ミーティングのKY活動時', '作業方法・手順・資機材を変更するとき', '給与計算を行うとき', '労働災害が発生したとき', 'C', 'RAは①朝の作業開始前KY時②作業方法等の変更時③作業計画書・要領書・手順書の作成時④労働災害発生時⑤監督官庁・会社が必要と認めるとき等に行う(第5条)。給与計算は無関係。', 'リスクアセスメント実施マニュアル 第5条', true),
  ('REG-019', '規程類', '健康管理', '★★', '定期健康診断の実施頻度として正しいものはどれか。', '2年に1回', '5年に1回', '採用時のみ', '毎年1回以上', 'D', '定期健康診断は、法令に定める検査項目の他、必要と認める項目について毎年1回以上行う(第21条)。', '健康管理マニュアル 第21条', true),
  ('REG-020', '規程類', '健康管理', '★★', '当社が実施する健康診断の3区分として正しいものはどれか。', '本人希望のみ', '入社時・中間・退職時', '月次・四半期・年次', '採用時・定期・特別', 'D', '会社は職員の健康管理のため『採用時健康診断・定期健康診断・特別健康診断』を実施する(第18条)。', '健康管理マニュアル 第18条', true),
  ('REG-021', '規程類', '健康管理', '★★★', '深夜業や有害業務などの特殊業務従事者に対して行う健康診断はどれか。', '特別(特殊業務従事者)健康診断', '定期健康診断', '採用時健康診断', '実施不要', 'A', '法第66条の深夜業・有害業務、特定業務従事者等には特別健康診断(特殊業務従事者健康診断等)を行う(第22条)。', '健康管理マニュアル 第22条', true),
  ('REG-022', '規程類', '健康管理', '★★', '健康診断等の健康管理業務に従事した職員の義務として正しいものはどれか。', '結果を朝礼で共有する', '知り得た秘密を漏らしてはならない(守秘義務)', '本人の同意なく上司へ通知する', 'SNSで注意喚起する', 'B', '健康管理業務に従事した職員は、当該職務により知り得た秘密を漏らしてはならない(守秘義務)(第25条)。', '健康管理マニュアル 第25条', true),
  ('REG-023', '規程類', '健康管理', '★', '職員(社員・契約・パート・アルバイト・派遣)の健康診断受診について正しいものはどれか。', '受診は任意で拒否できる', '受診結果の提出は不要', '管理職のみ受診すればよい', '所定の健康診断を受診し自己の健康保持に努める義務がある', 'D', '職員は所定の健康診断を受診し、自己の健康保持に努めなければならない。やむを得ず受診できないときは自ら医師の診断を受け結果を提出する(第19条)。', '健康管理マニュアル 第19条', true),
  ('REG-024', '規程類', 'リスクアセスメント', '★★', 'リスクアセスメントで現場でのリスク低減対策ができない場合の正しい対応はどれか。', '対策せず作業を進める', '作業員の自己判断に委ねる', '店社(本社・地域事務所)に報告し応援を求める', '翌月の会議まで保留する', 'C', '実施管理者は、現場でリスク低減対策ができない場合、店社(本社・地域事務所)に報告して応援を求めなければならない(第7条)。', 'リスクアセスメント実施マニュアル 第7条', true),
  ('REG-025', '規程類', '管理体制', '★', '職場小集団活動(KY活動)の説明として正しいものはどれか。', '経営方針を決定する会議', '職場の安全衛生の問題点を小集団で解決する自主活動', '懲戒を審議する委員会', '賃金を交渉する場', 'B', '職場小集団活動(KY活動)は、リーダーがメンバーを招集し職場の安全衛生の問題点を解決・実施することで自主活動の活発化を図る(第25条)。', '安全衛生管理規程 第25条', true),
  ('STANDARD-001', 'ベステラスタンダード', '総則', '★', '本規約(ベステラスタンダード)が対象とする工事はどれか。', '道路舗装工事', '新築建築工事', 'プラント解体工事', '造園工事', 'C', '本規約は、当社が行うプラント解体工事において関係法令を遵守し、安全かつ効率的な業務を遂行することを目的とする(第1章1)。', 'ベステラスタンダード 第1章 目的', true),
  ('STANDARD-002', 'ベステラスタンダード', '総則', '★', '本規約の適用範囲として正しいものはどれか。', '当社のすべての社員および協力会社', '正社員のみ', '監督職のみ', '客先従業員', 'A', '本規約は当社のすべての社員および協力会社に適用される(第1章2 適用範囲)。', 'ベステラスタンダード 第1章 適用範囲', true),
  ('STANDARD-003', 'ベステラスタンダード', '総則', '★★', 'ベステラスタンダードの主管部署はどこか。', '工事部', '経営企画部', '安全衛生室', '総務部', 'C', '作業場における法令遵守および安全管理規約の主管部署は安全衛生室である。', 'ベステラスタンダード 主管部署', true),
